	const E = (function () {
		const str = {
			'&': '&amp;',
			"'": '&#039;',
			'"': '&quot;',
			'<': '&lt;',
			'>': '&gt;'
		};
		const regex = /[&"'<>]/g;
		const fn = function (x) {
			return str[x];
		};
		const output = function (text) {
			return text.toString().replace(regex, fn);
		};
		output.cat = function (templates) {
			let html = '';
			for (let i = 0; i < templates.length; i++) {
				html += templates[i].innerHTML;
			}
			return html;
		};
		return output;
	})();
