	function view() {
		return d.defaultView || (typeof self !== 'undefined' ? self : null);
	}

	function isSupported() {
		const w = view();
		return !!(w && w.CSS && w.CSS.highlights && w.Highlight);
	}

	function wbrBridged(a, b) {
		if (a.parentNode !== b.parentNode)
			return false;
		for (let s = a.nextSibling; s && s !== b; s = s.nextSibling) {
			if (s.nodeType !== Node.ELEMENT_NODE || s.tagName !== 'WBR')
				return false;
		}
		return true;
	}

	function locateInRun(map, pos) {
		for (const e of map) {
			if (pos <= e.start + e.len)
				return { node: e.node, offset: pos - e.start };
		}
		const last = map[map.length - 1];
		return { node: last.node, offset: last.len };
	}

	function collectRunMatches(run, rx, ranges) {
		rx.lastIndex = 0;
		if (run.length === 1) {
			const node = run[0];
			const text = node.nodeValue || '';
			let m;
			while ((m = rx.exec(text))) {

				if (!m[0]) {
					rx.lastIndex++;
					continue;
				}
				const range = d.createRange();
				range.setStart(node, m.index);
				range.setEnd(node, m.index + m[0].length);
				ranges.push(range);
			}
			return;
		}
		let combined = '';
		const map = [];
		for (const node of run) {
			const len = (node.nodeValue || '').length;
			map.push({ node, start: combined.length, len });
			combined += node.nodeValue || '';
		}
		let m;
		while ((m = rx.exec(combined))) {
			if (!m[0]) {
				rx.lastIndex++;
				continue;
			}
			const s = locateInRun(map, m.index);
			const e = locateInRun(map, m.index + m[0].length);
			const range = d.createRange();
			range.setStart(s.node, s.offset);
			range.setEnd(e.node, e.offset);
			ranges.push(range);
		}
	}

	var SearchHighlight = {
		get supported() {
			return isSupported();
		},
		escape(s) {
			return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
		},

		rangesFor(root, rx) {
			const ranges = [];
			if (!root)
				return ranges;
			const walker = d.createTreeWalker(root, NodeFilter.SHOW_TEXT);
			const texts = [];
			let node;
			while ((node = walker.nextNode())) {
				if (node.nodeValue)
					texts.push(node);
			}
			for (let i = 0; i < texts.length;) {

				const run = [texts[i]];
				while (i + 1 < texts.length && wbrBridged(texts[i], texts[i + 1])) {
					run.push(texts[++i]);
				}
				i++;
				collectRunMatches(run, rx, ranges);
			}
			return ranges;
		},

		setRanges(name, ranges) {
			const w = view();
			if (!w || !w.CSS || !w.CSS.highlights || !w.Highlight)
				return false;
			if (ranges && ranges.length) {
				w.CSS.highlights.set(name, new w.Highlight(...ranges));
			} else {
				w.CSS.highlights.delete(name);
			}
			return true;
		},

		apply(name, roots, terms) {
			const w = view();
			if (!w || !w.CSS || !w.CSS.highlights || !w.Highlight)
				return false;
			const list = Array.isArray(roots) ? roots : [roots];
			if (!terms.length || !list.length) {
				w.CSS.highlights.delete(name);
				return true;
			}
			const rx = RegExp(terms.map(SearchHighlight.escape).join('|'), 'gi');
			const ranges = [];
			for (const root of list) {
				ranges.push(...SearchHighlight.rangesFor(root, rx));
			}
			return SearchHighlight.setRanges(name, ranges);
		},
		clear(name) {
			const w = view();
			if (w && w.CSS && w.CSS.highlights)
				w.CSS.highlights.delete(name);
		},
	};

